1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgMember, orgNameMode } from "@/lib/v2/orgs";
4	import { pickName } from "@/lib/v2/profile";
5	import { logActivity } from "@/lib/v2/activity";
6	import { syncEventChannelMembership } from "@/lib/v2/chat/channels";
7	
8	/**
9	 * RSVP for an event. Mirrors the legacy model: a member sets their attendance
10	 * *likelihood* (25/50/75/99). 99 ("Attending") marks them on_roster. DELETE
11	 * clears the RSVP. Returns the caller's likelihood plus the attending count
12	 * (on_roster). Auth: bearer (native) or cookie (web). Membership-gated.
13	 *
14	 * NOTE: the legacy site also cascades contest/roster enrollment on attend/leave.
15	 * v2 has no contest system yet, so we only persist likelihood + on_roster here;
16	 * enrollment sync lands when v2 contests do.
17	 */
18	
19	const LIKELIHOODS = [25, 50, 75, 99];
20	const LIKELIHOOD_LABEL: Record<number, string> = {
21	  99: "Attending",
22	  75: "Probable",
23	  50: "Questionable",
24	  25: "Doubtful",
25	};
26	
27	async function resolve(request: Request, eventId: string) {
28	  const { userId } = await v2GetUser(request);
29	  if (!userId) return { error: "Not authenticated", status: 401 as const };
30	  const admin = v2AdminClient();
31	  const { data: event } = await admin
32	    .from("v2_events")
33	    .select("id, org_id")
34	    .eq("id", eventId)
35	    .maybeSingle();
36	  if (!event) return { error: "Event not found", status: 404 as const };
37	  if (!(await isOrgMember(admin, userId, event.org_id))) {
38	    return { error: "Not a member", status: 403 as const };
39	  }
40	  return { admin, userId, orgId: event.org_id as string };
41	}
42	
43	async function attendingCount(
44	  admin: ReturnType<typeof v2AdminClient>,
45	  eventId: string,
46	): Promise<number> {
47	  const { count } = await admin
48	    .from("v2_event_participants")
49	    .select("id", { count: "exact", head: true })
50	    .eq("event_id", eventId)
51	    .eq("on_roster", true);
52	  return count ?? 0;
53	}
54	
55	export async function GET(
56	  request: Request,
57	  { params }: { params: Promise<{ eventId: string }> },
58	) {
59	  const { eventId } = await params;
60	  const g = await resolve(request, eventId);
61	  if ("error" in g) return NextResponse.json({ error: g.error }, { status: g.status });
62	
63	  const [{ data }, mode] = await Promise.all([
64	    g.admin
65	      .from("v2_event_participants")
66	      .select("user_id, likelihood, likelihood_set_at, on_roster, user:v2_profiles(display_name, first_name, last_name, avatar_url)")
67	      .eq("event_id", eventId),
68	    orgNameMode(g.admin, g.orgId),
69	  ]);
70	
71	  const rows = (data || []).map((r) => {
72	    const u = Array.isArray(r.user) ? r.user[0] : r.user;
73	    return {
74	      userId: r.user_id as string,
75	      likelihood: r.likelihood as number,
76	      likelihoodSetAt: (r.likelihood_set_at as string | null) ?? null,
77	      displayName: pickName(u, mode),
78	      avatarUrl: (u?.avatar_url as string | null) ?? null,
79	    };
80	  });
81	
82	  const mine = rows.find((r) => r.userId === g.userId);
83	  return NextResponse.json({
84	    likelihood: mine?.likelihood ?? null,
85	    attendingCount: (data || []).filter((r) => r.on_roster).length,
86	    responseCount: rows.length,
87	    participants: rows,
88	  });
89	}
90	
91	export async function POST(
92	  request: Request,
93	  { params }: { params: Promise<{ eventId: string }> },
94	) {
95	  const { eventId } = await params;
96	  const g = await resolve(request, eventId);
97	  if ("error" in g) return NextResponse.json({ error: g.error }, { status: g.status });
98	
99	  let body: { likelihood?: number };
100	  try {
101	    body = await request.json();
102	  } catch {
103	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
104	  }
105	  const likelihood = body.likelihood;
106	  if (!LIKELIHOODS.includes(likelihood as number)) {
107	    return NextResponse.json(
108	      { error: "likelihood must be 25, 50, 75, or 99" },
109	      { status: 400 },
110	    );
111	  }
112	  const onRoster = likelihood === 99;
113	
114	  // Pre-read prior likelihood so we log only a *genuine change* (not a re-confirm
115	  // of the same level). Any move between levels is feed-worthy.
116	  const { data: prior } = await g.admin
117	    .from("v2_event_participants")
118	    .select("likelihood")
119	    .eq("event_id", eventId)
120	    .eq("user_id", g.userId)
121	    .maybeSingle();
122	  const priorLikelihood = (prior?.likelihood as number | undefined) ?? null;
123	
124	  const { error } = await g.admin.from("v2_event_participants").upsert(
125	    {
126	      event_id: eventId,
127	      org_id: g.orgId,
128	      user_id: g.userId,
129	      likelihood,
130	      on_roster: onRoster,
131	      likelihood_set_at: new Date().toISOString(),
132	      updated_at: new Date().toISOString(),
133	    },
134	    { onConflict: "event_id,user_id" },
135	  );
136	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
137	
138	  // Managed event channel: opting in (on_roster) adds you with full history;
139	  // dropping below "Attending" removes you (your past messages stay). Best-effort.
140	  await syncEventChannelMembership(g.admin, eventId, g.userId, onRoster).catch(() => {});
141	
142	  // Activity feed: a row per genuine likelihood change. Title is the status only
143	  // ("Attending 99%") — the feed renders the actor's name + avatar itself.
144	  if (priorLikelihood !== likelihood) {
145	    await logActivity(g.admin, {
146	      orgId: g.orgId,
147	      eventId,
148	      kind: "rsvp",
149	      actorId: g.userId,
150	      title: `${LIKELIHOOD_LABEL[likelihood as number]} ${likelihood}%`,
151	      refId: eventId,
152	      metadata: { likelihood },
153	    }).catch(() => {});
154	  }
155	
156	  return NextResponse.json({
157	    likelihood,
158	    attendingCount: await attendingCount(g.admin, eventId),
159	  });
160	}
161	
162	export async function DELETE(
163	  request: Request,
164	  { params }: { params: Promise<{ eventId: string }> },
165	) {
166	  const { eventId } = await params;
167	  const g = await resolve(request, eventId);
168	  if ("error" in g) return NextResponse.json({ error: g.error }, { status: g.status });
169	
170	  const { error } = await g.admin
171	    .from("v2_event_participants")
172	    .delete()
173	    .eq("event_id", eventId)
174	    .eq("user_id", g.userId);
175	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
176	
177	  // Clearing an RSVP drops you from the event channel (messages persist).
178	  await syncEventChannelMembership(g.admin, eventId, g.userId, false).catch(() => {});
179	
180	  return NextResponse.json({
181	    likelihood: null,
182	    attendingCount: await attendingCount(g.admin, eventId),
183	  });
184	}
