3	/** Unified activity-feed model for v2. Forward-only: features append as events happen. */
4	
5	export type ActivityKind = "round" | "photo" | "song" | "article" | "announcement" | "rsvp";
6	
7	export interface ActivityRow {
8	  id: string;
9	  kind: string;
10	  title: string;
11	  subtitle: string | null;
12	  image_url: string | null;
13	  link: string | null;
14	  created_at: string;
15	  ref_id: string | null;
16	  metadata: Record<string, unknown> | null;
17	  actor: {
18	    display_name: string;
19	    first_name?: string | null;
20	    last_name?: string | null;
21	    avatar_url: string | null;
22	  } | null;
23	}
24	
25	export interface LogActivityInput {
26	  orgId: string;
27	  eventId?: string | null;
28	  kind: ActivityKind | string;
29	  actorId?: string | null;
30	  title: string;
31	  subtitle?: string | null;
32	  imageUrl?: string | null;
33	  link?: string | null;
34	  refId?: string | null;
35	  metadata?: Record<string, unknown>;
36	}
37	
38	/**
39	 * Append an event to the activity feed. Call from the feature that generated it
40	 * (server-side, with a service-role client). Best-effort — callers should not let
41	 * a feed-log failure break the primary action.
42	 */
43	export async function logActivity(
44	  admin: SupabaseClient,
45	  input: LogActivityInput,
46	): Promise<void> {
47	  await admin.from("v2_activity").insert({
48	    org_id: input.orgId,
49	    event_id: input.eventId ?? null,
50	    kind: input.kind,
51	    actor_id: input.actorId ?? null,
52	    title: input.title,
53	    subtitle: input.subtitle ?? null,
54	    image_url: input.imageUrl ?? null,
55	    link: input.link ?? null,
56	    ref_id: input.refId ?? null,
57	    metadata: input.metadata ?? {},
58	  });
59	}
