61	/** Compact relative time, e.g. "just now", "3h ago", "2d ago", "Aug 14". */
62	export function timeAgo(iso: string, now = new Date()): string {
63	  const then = new Date(iso).getTime();
64	  const secs = Math.max(0, Math.floor((now.getTime() - then) / 1000));
65	  if (secs < 60) return "just now";
66	  const mins = Math.floor(secs / 60);
67	  if (mins < 60) return `${mins}m ago`;
68	  const hrs = Math.floor(mins / 60);
69	  if (hrs < 24) return `${hrs}h ago`;
70	  const days = Math.floor(hrs / 24);
71	  if (days < 7) return `${days}d ago`;
72	  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric" });
73	}
