1	-- v2 chat schema. Mirrors the legacy chat model (rooms/members/messages/
2	-- reactions/read_receipts/hidden_messages) but org-scoped and v2-owned. History
3	-- is imported separately (00196) preserving original UUIDs, so IDs here are plain
4	-- uuid PKs (default gen_random_uuid for NEW rows). All user refs point at
5	-- v2_profiles (same id space as legacy users; all migrated).
6	
7	DROP TABLE IF EXISTS public.v2_chat_hidden_messages;
8	DROP TABLE IF EXISTS public.v2_chat_read_receipts;
9	DROP TABLE IF EXISTS public.v2_chat_reactions;
10	DROP TABLE IF EXISTS public.v2_chat_messages;
11	DROP TABLE IF EXISTS public.v2_chat_room_members;
12	DROP TABLE IF EXISTS public.v2_chat_rooms;
13	DROP FUNCTION IF EXISTS public.v2_is_chat_member(UUID);
14	DROP FUNCTION IF EXISTS public.v2_is_message_room_member(UUID);
15	
16	CREATE TABLE public.v2_chat_rooms (
17	  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
18	  org_id     UUID NOT NULL REFERENCES public.v2_organizations(id) ON DELETE CASCADE,
19	  event_id   UUID REFERENCES public.v2_events(id) ON DELETE SET NULL,
20	  type       TEXT NOT NULL CHECK (type IN ('group', 'dm')),
21	  name       TEXT,
22	  created_by UUID REFERENCES public.v2_profiles(id) ON DELETE SET NULL,
23	  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
24	);
25	CREATE INDEX idx_v2_chat_rooms_org ON public.v2_chat_rooms(org_id);
26	
27	CREATE TABLE public.v2_chat_room_members (
28	  id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
29	  room_id   UUID NOT NULL REFERENCES public.v2_chat_rooms(id) ON DELETE CASCADE,
30	  user_id   UUID NOT NULL REFERENCES public.v2_profiles(id) ON DELETE CASCADE,
31	  role      TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('creator', 'member')),
32	  is_pinned BOOLEAN NOT NULL DEFAULT false,
33	  hidden_at TIMESTAMPTZ,
34	  joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
35	  UNIQUE (room_id, user_id)
36	);
37	CREATE INDEX idx_v2_chat_members_user ON public.v2_chat_room_members(user_id);
38	CREATE INDEX idx_v2_chat_members_room ON public.v2_chat_room_members(room_id);
39	
40	CREATE TABLE public.v2_chat_messages (
41	  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
42	  room_id     UUID NOT NULL REFERENCES public.v2_chat_rooms(id) ON DELETE CASCADE,
43	  sender_id   UUID NOT NULL REFERENCES public.v2_profiles(id) ON DELETE CASCADE,
44	  content     TEXT,
45	  image_url   TEXT,
46	  reply_to_id UUID REFERENCES public.v2_chat_messages(id) ON DELETE SET NULL,
47	  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
48	  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
49	  CONSTRAINT v2_chat_content_or_image CHECK (content IS NOT NULL OR image_url IS NOT NULL)
50	);
51	-- Supports realtime + cursor-based reverse pagination (load older on scroll-up).
52	CREATE INDEX idx_v2_chat_messages_room_created
53	  ON public.v2_chat_messages(room_id, created_at DESC);
54	
55	CREATE TABLE public.v2_chat_reactions (
56	  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
57	  message_id UUID NOT NULL REFERENCES public.v2_chat_messages(id) ON DELETE CASCADE,
58	  user_id    UUID NOT NULL REFERENCES public.v2_profiles(id) ON DELETE CASCADE,
59	  emoji      TEXT NOT NULL,
60	  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
61	  UNIQUE (message_id, user_id, emoji)
62	);
63	CREATE INDEX idx_v2_chat_reactions_message ON public.v2_chat_reactions(message_id);
64	
65	CREATE TABLE public.v2_chat_read_receipts (
66	  room_id              UUID NOT NULL REFERENCES public.v2_chat_rooms(id) ON DELETE CASCADE,
67	  user_id              UUID NOT NULL REFERENCES public.v2_profiles(id) ON DELETE CASCADE,
68	  last_read_message_id UUID REFERENCES public.v2_chat_messages(id) ON DELETE SET NULL,
69	  last_read_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
70	  PRIMARY KEY (room_id, user_id)
71	);
72	
73	CREATE TABLE public.v2_chat_hidden_messages (
74	  user_id    UUID NOT NULL REFERENCES public.v2_profiles(id) ON DELETE CASCADE,
75	  message_id UUID NOT NULL REFERENCES public.v2_chat_messages(id) ON DELETE CASCADE,
76	  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
77	  PRIMARY KEY (user_id, message_id)
78	);
79	
80	-- ── Membership helpers (SECURITY DEFINER — avoid RLS recursion) ───────────────
81	CREATE FUNCTION public.v2_is_chat_member(p_room UUID)
82	RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$
83	  SELECT EXISTS (
84	    SELECT 1 FROM public.v2_chat_room_members m
85	    WHERE m.room_id = p_room AND m.user_id = auth.uid()
86	  );
87	$$;
88	
89	CREATE FUNCTION public.v2_is_message_room_member(p_message UUID)
90	RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$
91	  SELECT EXISTS (
92	    SELECT 1
93	    FROM public.v2_chat_messages msg
94	    JOIN public.v2_chat_room_members m ON m.room_id = msg.room_id
95	    WHERE msg.id = p_message AND m.user_id = auth.uid()
96	  );
97	$$;
98	
99	-- ── RLS ───────────────────────────────────────────────────────────────────────
100	ALTER TABLE public.v2_chat_rooms          ENABLE ROW LEVEL SECURITY;
101	ALTER TABLE public.v2_chat_room_members   ENABLE ROW LEVEL SECURITY;
102	ALTER TABLE public.v2_chat_messages       ENABLE ROW LEVEL SECURITY;
103	ALTER TABLE public.v2_chat_reactions      ENABLE ROW LEVEL SECURITY;
104	ALTER TABLE public.v2_chat_read_receipts  ENABLE ROW LEVEL SECURITY;
105	ALTER TABLE public.v2_chat_hidden_messages ENABLE ROW LEVEL SECURITY;
106	
107	CREATE POLICY "v2_room_select" ON public.v2_chat_rooms FOR SELECT
108	  TO authenticated USING (public.v2_is_chat_member(id));
109	CREATE POLICY "v2_room_insert" ON public.v2_chat_rooms FOR INSERT
110	  TO authenticated WITH CHECK (created_by = auth.uid() AND public.v2_is_org_member(org_id));
111	
112	CREATE POLICY "v2_member_select" ON public.v2_chat_room_members FOR SELECT
113	  TO authenticated USING (user_id = auth.uid() OR public.v2_is_chat_member(room_id));
114	CREATE POLICY "v2_member_update_own" ON public.v2_chat_room_members FOR UPDATE
115	  TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
116	
117	CREATE POLICY "v2_msg_select" ON public.v2_chat_messages FOR SELECT
118	  TO authenticated USING (public.v2_is_chat_member(room_id));
119	CREATE POLICY "v2_msg_insert" ON public.v2_chat_messages FOR INSERT
120	  TO authenticated WITH CHECK (sender_id = auth.uid() AND public.v2_is_chat_member(room_id));
121	
122	CREATE POLICY "v2_reaction_select" ON public.v2_chat_reactions FOR SELECT
123	  TO authenticated USING (public.v2_is_message_room_member(message_id));
124	CREATE POLICY "v2_reaction_write" ON public.v2_chat_reactions FOR ALL
125	  TO authenticated
126	  USING (user_id = auth.uid() AND public.v2_is_message_room_member(message_id))
127	  WITH CHECK (user_id = auth.uid() AND public.v2_is_message_room_member(message_id));
128	
129	CREATE POLICY "v2_receipt_manage_own" ON public.v2_chat_read_receipts FOR ALL
130	  TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
131	
132	CREATE POLICY "v2_hidden_manage_own" ON public.v2_chat_hidden_messages FOR ALL
133	  TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
134	
135	-- ── Grants ────────────────────────────────────────────────────────────────────
