11	const OPTIONS: { value: Likelihood; label: string; description: string }[] = [
12	  { value: 99, label: "Attending", description: "99% - I'll be there" },
13	  { value: 75, label: "Probable", description: "75% - Looking good" },
14	  { value: 50, label: "Questionable", description: "50% - Still figuring it out" },
15	  { value: 25, label: "Doubtful", description: "25% - Unlikely but possible" },
16	];
17	
18	const LABEL: Record<Likelihood, string> = {
19	  99: "Attending",
20	  75: "Probable",
21	  50: "Questionable",
22	  25: "Doubtful",
23	};
24	
25	interface Participant {
26	  userId: string;
27	  likelihood: number;
28	  likelihoodSetAt: string | null;
29	  displayName: string;
30	  avatarUrl: string | null;
31	}
