33	/**
34	 * Event RSVP. Until the user responds it's a bold, pulsing brand CTA; once they
35	 * do it becomes a "Responses" accordion (mirrors legacy): their own response +
36	 * an expandable breakdown of everyone's choice grouped by likelihood. Writes to
37	 * /api/v2/events/[eventId]/rsvp (cookie auth on web).
38	 */
39	export default function RsvpModule({
40	  eventId,
41	  eventName,
42	  initialLikelihood,
43	  initialResponseCount,
44	  initialAttendingCount,
45	}: {
46	  eventId: string;
47	  eventName: string;
48	  initialLikelihood: Likelihood | null;
49	  initialResponseCount: number;
50	  initialAttendingCount: number;
