59	  const [error, setError] = useState<string | null>(null);
60	
61	  const loadParticipants = useCallback(async () => {
62	    try {
63	      const res = await fetch(`/api/v2/events/${eventId}/rsvp`);
64	      if (!res.ok) return;
65	      const d = await res.json();
66	      setParticipants(d.participants || []);
67	      setResponseCount(d.responseCount ?? 0);
68	      setAttendingCount(d.attendingCount ?? 0);
69	      setLikelihood(d.likelihood ?? null);
70	    } catch {
71	      /* ignore */
72	    }
73	  }, [eventId]);
